import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks every page of a keyset-paginated listing, so a rebuild reaches every
 * row however many there are rather than only the first page.
 */
async function* walkAllPages<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
): AsyncGenerator<T> {
  let cursor: string | null = null;
  do {
    const page: Page<T> = await fetchPage(cursor);
    for (const item of page.items) yield item;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 *
 * Only live content is indexed: archived issues and deleted comments are
 * skipped, and documents left over from earlier runs are pruned at the end.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const startedAt = toIsoTimestamp(new Date());

    for await (const project of walkAllPages((cursor) =>
      projectRepo.listProjects({ orgId, limit: PAGE_SIZE, cursor }),
    )) {
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    for await (const issue of walkAllPages((cursor) =>
      issueRepo.listIssues({ orgId, limit: PAGE_SIZE, cursor }),
    )) {
      try {
        await indexIssue(orgId, issue);
        result.processed += 1;

        // Live comments only, replies included: a live reply keeps its place
        // even when its parent comment has been deleted.
        for await (const comment of walkAllPages((cursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: false,
            limit: PAGE_SIZE,
            cursor,
          }),
        )) {
          await indexComment(orgId, comment);
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index issue", {
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    await searchRepo.pruneSearchDocuments(orgId, startedAt);
  });
}

